node --input-type=module <<'EOF' 2>&1 | tee /opt/cursor/artifacts/refund-verification.log
import assert from 'node:assert/strict';
import { createRefund } from './impl.ts';

const payment = { id: 'pay_1', merchantId: 'merchant_1', amountCents: 1000, refundedCents: 200, status: 'succeeded' };
const request = { id: 'req_1', merchantId: 'merchant_1', paymentId: 'pay_1' };

const fullRemaining = createRefund(request, payment);
assert.equal(fullRemaining.status, 201);
assert.equal(fullRemaining.refundedCents, 800);
assert.match(fullRemaining.refundId, /^[0-9a-f-]{36}$/);
assert.equal(payment.refundedCents, 200);

assert.equal(createRefund({ ...request, amountCents: 300 }, payment).refundedCents, 300);
assert.equal(createRefund(request, { ...payment, status: 'pending' }).status, 201);
assert.deepEqual(createRefund({ ...request, amountCents: 801 }, payment), { status: 409, refundedCents: 0, error: 'refund amount exceeds payment balance' });
assert.equal(createRefund(request, { ...payment, refundedCents: 1000 }).status, 409);
assert.equal(createRefund(request, { ...payment, status: 'failed' }).status, 409);
assert.equal(createRefund({ ...request, paymentId: 'other' }, payment).status, 404);
assert.equal(createRefund({ ...request, merchantId: 'other' }, payment).status, 403);
for (const amountCents of [0, -1, 1.5, Number.NaN, Number.MAX_SAFE_INTEGER + 1]) {
  assert.equal(createRefund({ ...request, amountCents }, payment).status, 400);
}
console.log('PASS: success, defaults, partial/pending refunds, limits, ownership, state, and amount validation');
EOF
